import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create plane geometry with aspect ratio from atlas region (512:320 ≈ 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Load texture from cache
  const texture = ctx.textureLoader.load(
    config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png'
  );

  // Static material - engineered surface with no special lighting effects
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create and configure mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position and transforms
  if (config.scenePosition) {
    mesh.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );

    if (config.scenePosition.rotationXYZ) {
      const [rx, ry, rz] = config.scenePosition.rotationXYZ;
      mesh.rotation.set(rx, ry, rz);
    }

    if (config.scenePosition.scaleXYZ) {
      const [sx, sy, sz] = config.scenePosition.scaleXYZ;
      mesh.scale.set(sx, sy, sz);
    }
  }

  group.add(mesh);

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // No event handlers (static composition)
  group.userData.handlers = {};

  return group;
}
